import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { ArrowDown, ArrowUpRight, Check, ChevronDown, Mail } from 'lucide-react'
import atelier1100 from './assets/atelier-plate-1100.jpg'
import atelier640 from './assets/atelier-plate-640.jpg'

// The power path, in the order energy actually travels. This order is a fact
// about the movement, not a layout decision.
const POWER_PATH = [
  {
    id: 'mainspring',
    name: 'Mainspring',
    detail: 'A 380mm hardened alloy ribbon, wound to 6.5 turns.',
    figure: '72 hours of stored energy at full wind',
  },
  {
    id: 'barrel',
    name: 'Barrel and stop-work',
    detail: 'Releases the spring at a near-constant torque and refuses the last eight per cent, where the rate would drift.',
    figure: 'Torque held within 4% across the run',
  },
  {
    id: 'train',
    name: 'Gear train',
    detail: 'Four wheels step the barrel’s one slow turn up to the escape wheel’s fast one.',
    figure: 'Ratio 1 : 4,608',
  },
  {
    id: 'escapement',
    name: 'Escapement',
    detail: 'A free-sprung lever in silicon releases the train one tooth at a time. This is the ticking.',
    figure: '5 releases per second',
  },
  {
    id: 'balance',
    name: 'Balance wheel',
    detail: 'A 10.6mm glucydur wheel swinging against a flat hairspring. Its period is what the watch calls a second.',
    figure: '18,000 semi-oscillations per hour',
  },
  {
    id: 'hands',
    name: 'Motion work and hands',
    detail: 'The last reduction divides that swing back down into minutes and hours.',
    figure: 'Cumulative deviation −1 to +4 seconds per day',
  },
]

// Physical layers, front of the movement to back. Also a fact, not an order
// chosen for the page.
const LAYERS = [
  { id: 'dial-side', name: 'Dial-side plate', thickness: '0.9mm', note: 'Carries the motion work and the hand posts.' },
  { id: 'main', name: 'Main plate', thickness: '1.4mm', note: 'German silver, frosted by hand. Every pivot is located from this one surface.' },
  { id: 'bridge', name: 'Train bridge', thickness: '0.8mm', note: 'One continuous bridge over all four train wheels, black-polished on the upper flanks.' },
  { id: 'balance-cock', name: 'Balance cock', thickness: '0.7mm', note: 'Holds the balance from one side only, so the wheel can be seen turning.' },
]

const CONFIGURATIONS = [
  {
    id: 'frosted',
    name: 'Frosted German silver',
    finish: 'Hand-frosted plates, straight-grained bridges, blued screws.',
    price: 24800,
    lead: 'Delivered from March 2027',
    remaining: 41,
  },
  {
    id: 'skeleton',
    name: 'Open-worked',
    finish: 'Main plate cut back to the load paths, every remaining edge anglaged by hand.',
    price: 39500,
    lead: 'Delivered from September 2027',
    remaining: 12,
  },
  {
    id: 'black',
    name: 'Black-polished steel',
    finish: 'Bridges polished to a true black at every angle, matte plates for contrast.',
    price: 31200,
    lead: 'Delivered from June 2027',
    remaining: 24,
  },
]

const SPECS = [
  ['Reference', 'Caliber 08'],
  ['Diameter', '31.0mm'],
  ['Height', '3.8mm'],
  ['Jewels', '27'],
  ['Frequency', '2.5 Hz (18,000 A/h)'],
  ['Power reserve', '72 hours'],
  ['Regulation', 'Free-sprung, four inertia weights'],
  ['Winding', 'Manual'],
  ['Components', '214'],
  ['Finishing hours', '62 per movement'],
]

const ATELIER = [
  'Designed, cut, and finished at the workshop in Vallée de Joux. Nothing is subcontracted except the jewels and the mainspring.',
  'Eleven watchmakers. Two of them do nothing but finishing.',
  'A total of 200 movements will be made, after which the tooling is retired.',
  'Every movement is run for 21 days in six positions before it leaves. The timing record ships with it.',
  'Serviceable indefinitely. We keep parts for retired calibers and will not stop.',
]

const NAV = [
  ['power-path', 'Power path'],
  ['layers', 'Layers'],
  ['specification', 'Specification'],
  ['workshop', 'Workshop'],
  ['finishes', 'Finishes'],
  ['reserve', 'Reserve'],
]

const chf = (n) => n.toLocaleString('en-CH')
const pad = (n) => String(n).padStart(2, '0')

/* ------------------------------------------------------------------ *
 * Drawing helpers. Real geometry, generated — these are schematics of
 * the movement, not photographs of it.
 * ------------------------------------------------------------------ */

function gearPath(cx, cy, r, teeth, depth = 0.14) {
  const inner = r * (1 - depth)
  const pts = []
  const step = (Math.PI * 2) / teeth
  for (let i = 0; i < teeth; i += 1) {
    const a0 = i * step
    const a1 = a0 + step * 0.42
    const a2 = a0 + step * 0.5
    const a3 = a0 + step * 0.92
    pts.push(`${cx + Math.cos(a0) * r} ${cy + Math.sin(a0) * r}`)
    pts.push(`${cx + Math.cos(a1) * r} ${cy + Math.sin(a1) * r}`)
    pts.push(`${cx + Math.cos(a2) * inner} ${cy + Math.sin(a2) * inner}`)
    pts.push(`${cx + Math.cos(a3) * inner} ${cy + Math.sin(a3) * inner}`)
  }
  return `M ${pts.join(' L ')} Z`
}

function spiralPath(cx, cy, r0, r1, turns, points = 180) {
  const d = []
  for (let i = 0; i <= points; i += 1) {
    const t = i / points
    const a = t * turns * Math.PI * 2
    const r = r0 + (r1 - r0) * t
    d.push(`${i === 0 ? 'M' : 'L'} ${(cx + Math.cos(a) * r).toFixed(2)} ${(cy + Math.sin(a) * r).toFixed(2)}`)
  }
  return d.join(' ')
}

// 27 jewels, placed at the pivots and pallets they actually sit on.
const JEWELS = [
  [148, 156], [148, 132], [176, 178], [200, 150], [214, 120], [240, 104],
  [246, 138], [268, 160], [258, 190], [232, 206], [212, 232], [236, 244],
  [190, 250], [166, 236], [150, 262], [128, 284], [128, 306], [104, 292],
  [104, 268], [154, 300], [176, 296], [186, 274], [124, 336], [152, 330],
  [206, 176], [222, 262], [172, 210],
]

function MovementPlate() {
  return (
    <svg className="plate-svg" viewBox="0 0 400 400" role="img"
      aria-label="Schematic top view of Caliber 08: barrel, four-wheel train, lever escapement and balance wheel inside a 31mm main plate.">
      <defs>
        <clipPath id="plateClip"><circle cx="196" cy="200" r="152" /></clipPath>
      </defs>

      {/* main plate */}
      <circle className="ln-plate" cx="196" cy="200" r="152" />
      <circle className="ln-hair" cx="196" cy="200" r="146" />

      <g clipPath="url(#plateClip)">
        {/* frosting texture: concentric turning marks */}
        <g className="ln-frost">
          {Array.from({ length: 14 }, (_, i) => (
            <circle key={i} cx="196" cy="200" r={20 + i * 10} />
          ))}
        </g>

        {/* barrel + mainspring */}
        <path className="ln-part" d={gearPath(148, 152, 62, 64, 0.06)} />
        <path className="ln-spring" d={spiralPath(148, 152, 9, 50, 5.5)} />
        <circle className="ln-part" cx="148" cy="152" r="7" />

        {/* train, barrel -> escape wheel */}
        <path className="ln-part" d={gearPath(232, 128, 40, 48, 0.08)} />
        <circle className="ln-hair" cx="232" cy="128" r="12" />
        <path className="ln-part" d={gearPath(258, 192, 32, 40, 0.09)} />
        <circle className="ln-hair" cx="258" cy="192" r="10" />
        <path className="ln-part" d={gearPath(216, 236, 26, 32, 0.1)} />
        <circle className="ln-hair" cx="216" cy="236" r="8" />

        {/* escape wheel */}
        <path className="ln-escape" d={gearPath(166, 240, 22, 15, 0.34)} />
        <circle className="ln-hair" cx="166" cy="240" r="5" />

        {/* pallet lever */}
        <path className="ln-part" d="M 166 268 L 150 288 L 132 292 L 130 300 L 148 300 L 168 280 Z" />

        {/* balance cock, drawn over the balance */}
        <path className="ln-bridge" d="M 62 250 C 96 236 140 246 156 282 C 168 310 158 344 128 356 C 96 368 62 350 58 316 Z" />

        {/* balance wheel — the moving part */}
        <g className="balance">
          <g className="balance-spin">
            <circle className="ln-part" cx="112" cy="306" r="54" />
            <circle className="ln-hair" cx="112" cy="306" r="47" />
            {[0, 90, 180, 270].map((a) => (
              <circle key={a} className="ln-weight" cx={112 + Math.cos((a * Math.PI) / 180) * 50}
                cy={306 + Math.sin((a * Math.PI) / 180) * 50} r="6" />
            ))}
            <path className="ln-part" d="M 58 306 H 166 M 112 252 V 360" />
            <path className="ln-spring" d={spiralPath(112, 306, 5, 30, 4.5)} />
          </g>
          <circle className="ln-pivot" cx="112" cy="306" r="4" />
        </g>

        {/* jewels */}
        {JEWELS.map(([x, y], i) => <circle key={i} className="jewel" cx={x} cy={y} r="3.4" />)}
      </g>

      {/* dimension callout */}
      <g className="dim">
        <path d="M 44 200 H 36 M 40 200 H 40 M 40 48 V 352 M 348 48 V 352" />
        <path className="dim-arrow" d="M 40 200 H 348" />
        <text x="194" y="192" textAnchor="middle">⌀ 31.0 mm</text>
      </g>

      {/* leaders */}
      <g className="leader">
        <path d="M 148 152 L 74 96 L 34 96" />
        <text x="34" y="88">Barrel</text>
        <path d="M 232 128 L 316 72 L 366 72" />
        <text x="366" y="64" textAnchor="end">Train</text>
        <path d="M 166 240 L 300 330 L 366 330" />
        <text x="366" y="322" textAnchor="end">Escapement</text>
        <path d="M 112 306 L 60 380 L 34 380" />
        <text x="34" y="394">Balance, 2.5 Hz</text>
      </g>
    </svg>
  )
}

function StageGlyph({ id }) {
  const c = { viewBox: '0 0 48 48', className: 'glyph', 'aria-hidden': 'true' }
  switch (id) {
    case 'mainspring':
      return <svg {...c}><path d={spiralPath(24, 24, 2, 20, 4)} /></svg>
    case 'barrel':
      return <svg {...c}><path d={gearPath(24, 24, 19, 34, 0.08)} /><circle cx="24" cy="24" r="6" /><path d="M24 6 V 18" /></svg>
    case 'train':
      return (
        <svg {...c}>
          <path d={gearPath(15, 15, 11, 18, 0.16)} />
          <path d={gearPath(33, 24, 8, 14, 0.18)} />
          <path d={gearPath(20, 36, 6, 12, 0.2)} />
        </svg>
      )
    case 'escapement':
      return (
        <svg {...c}>
          <path d={gearPath(19, 21, 13, 15, 0.36)} />
          <circle cx="19" cy="21" r="3" />
          <path d="M 30 28 L 38 36 L 44 36" />
          <path d="M 26 30 L 32 40" />
        </svg>
      )
    case 'balance':
      return (
        <svg {...c}>
          <circle cx="24" cy="24" r="19" /><path d="M5 24 H43 M24 5 V43" />
          {[0, 90, 180, 270].map((a) => (
            <circle key={a} cx={24 + Math.cos((a * Math.PI) / 180) * 17} cy={24 + Math.sin((a * Math.PI) / 180) * 17} r="3" />
          ))}
        </svg>
      )
    default:
      return (
        <svg {...c}>
          <circle cx="24" cy="24" r="19" />
          <path d="M24 24 V 10 M24 24 L 34 30" />
          <circle cx="24" cy="24" r="2.5" />
        </svg>
      )
  }
}

/* ------------------------------------------------------------------ *
 * Reveal + liveness. One shared observer grammar for the whole route.
 * ------------------------------------------------------------------ */

function useInView(options) {
  const ref = useRef(null)
  const [seen, setSeen] = useState(false)
  const { once = true, margin = '0px 0px -14% 0px', threshold = 0.12 } = options || {}
  useEffect(() => {
    const el = ref.current
    if (!el) return undefined
    if (typeof IntersectionObserver === 'undefined') { setSeen(true); return undefined }
    const io = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setSeen(true)
          if (once) io.disconnect()
        } else if (!once) setSeen(false)
      },
      { rootMargin: margin, threshold },
    )
    io.observe(el)
    return () => io.disconnect()
  }, [once, margin, threshold])
  return [ref, seen]
}

function Section({ id, fig, label, children, tone }) {
  const [ref, seen] = useInView()
  return (
    <section id={id} ref={ref} className={`section${tone ? ` section--${tone}` : ''}${seen ? ' is-in' : ''}`}>
      <div className="section__rail">
        <span className="fig">Fig. {fig}</span>
        <span className="fig-label">{label}</span>
      </div>
      <div className="section__body">{children}</div>
    </section>
  )
}

/* ------------------------------------------------------------------ *
 * Sections
 * ------------------------------------------------------------------ */

function PowerPath() {
  const [active, setActive] = useState(null)
  const [ref, live] = useInView({ once: false, margin: '0px', threshold: 0 })
  return (
    <div className={`path${live ? ' is-live' : ''}`} ref={ref}>
      <ol className="path__list">
        {POWER_PATH.map((s, i) => (
          <li
            key={s.id}
            className={`stage${active === s.id ? ' is-active' : ''}`}
            style={{ '--i': i }}
            onMouseEnter={() => setActive(s.id)}
            onMouseLeave={() => setActive(null)}
            onFocus={() => setActive(s.id)}
            onBlur={() => setActive(null)}
            tabIndex={0}
          >
            <div className="stage__spine" aria-hidden="true">
              <span className="stage__node"><StageGlyph id={s.id} /></span>
            </div>
            <div className="stage__text">
              <p className="stage__name"><span className="stage__no">{pad(i + 1)}</span>{s.name}</p>
              <p className="stage__detail">{s.detail}</p>
            </div>
            <p className="stage__figure">{s.figure}</p>
          </li>
        ))}
      </ol>
      <p className="path__foot" aria-hidden="true">
        <span className="pulse-key" /> One wind, tracked from spring to hands
      </p>
    </div>
  )
}

const MM = 30 // px per millimetre in the exploded elevation
const GAP = 30

function LayerStack() {
  const [active, setActive] = useState(null)
  const [ref, seen] = useInView({ margin: '0px 0px -20% 0px', threshold: 0.2 })

  const plates = useMemo(() => {
    let y = 26
    return LAYERS.map((l) => {
      const h = parseFloat(l.thickness) * MM
      const item = { ...l, y, h }
      y += h + GAP
      return item
    })
  }, [])
  const height = plates[plates.length - 1].y + plates[plates.length - 1].h + 30

  return (
    <div className={`stack${seen ? ' is-in' : ''}`} ref={ref}>
      <svg className="stack__svg" viewBox={`0 0 460 ${height}`} role="img"
        aria-label="Exploded elevation of the four plates, drawn to their real thicknesses, 3.8mm in total.">
        <g className="stack__axis">
          <path d={`M 24 20 V ${height - 20}`} />
          <text x="34" y="26">front</text>
          <text x="34" y={height - 22}>back</text>
        </g>
        {plates.map((p, i) => (
          <g key={p.id} className={`plateg${active === p.id ? ' is-active' : ''}`} style={{ '--i': i }}
            onMouseEnter={() => setActive(p.id)} onMouseLeave={() => setActive(null)}>
            {/* isometric slab: top face + front face, thickness to scale */}
            <path className="plateg__top" d={`M 96 ${p.y} L 316 ${p.y - 40} L 436 ${p.y} L 216 ${p.y + 40} Z`} />
            <path className="plateg__side" d={`M 96 ${p.y} L 96 ${p.y + p.h} L 216 ${p.y + 40 + p.h} L 216 ${p.y + 40} Z`} />
            <path className="plateg__side2" d={`M 216 ${p.y + 40} L 216 ${p.y + 40 + p.h} L 436 ${p.y + p.h} L 436 ${p.y} Z`} />
            <path className="plateg__lead" d={`M 92 ${p.y + 4} H 56`} />
            <text className="plateg__mm" x="52" y={p.y + 8} textAnchor="end">{p.thickness}</text>
          </g>
        ))}
      </svg>
      <ol className="stack__list">
        {LAYERS.map((l, i) => (
          <li key={l.id} className={`layer${active === l.id ? ' is-active' : ''}`}
            onMouseEnter={() => setActive(l.id)} onMouseLeave={() => setActive(null)}
            onFocus={() => setActive(l.id)} onBlur={() => setActive(null)} tabIndex={0}>
            <span className="layer__no">{pad(i + 1)}</span>
            <span className="layer__name">{l.name}</span>
            <span className="layer__mm">{l.thickness}</span>
            <span className="layer__note">{l.note}</span>
          </li>
        ))}
      </ol>
      <p className="stack__total"><span>3.8mm</span> assembled, dial-side plate to balance cock</p>
    </div>
  )
}

export default function App() {
  const [config, setConfig] = useState('')
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [reserved, setReserved] = useState(false)
  const formRef = useRef(null)

  const chosen = CONFIGURATIONS.find((c) => c.id === config)

  function handleSubmit(e) {
    e.preventDefault()
    if (!name || !email || !config) return
    setReserved(true)
  }

  const pick = useCallback((id) => {
    setConfig(id)
    const el = document.getElementById('reserve')
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' })
  }, [])

  return (
    <div className="page">
      <header className="topbar">
        <a className="topbar__mark" href="#top">
          <span className="topbar__house">Aubry &amp; Vent</span>
          <span className="topbar__cal">Caliber 08</span>
        </a>
        <nav className="topbar__nav" aria-label="Sections of this page">
          {NAV.map(([id, label]) => (
            <a key={id} href={`#${id}`}>{label}</a>
          ))}
        </nav>
        <p className="beat" title="The balance runs at 2.5 Hz">
          <span className="beat__mark" aria-hidden="true"><span /></span>
          <span className="beat__hz">2.5 Hz</span>
        </p>
      </header>

      <main id="top">
        {/* ---------------------------------------------------- Fig. 01 */}
        <section className="hero" aria-labelledby="hero-title">
          <div className="hero__text">
            <p className="eyebrow">Fig. 01 &nbsp;·&nbsp; Vallée de Joux &nbsp;·&nbsp; MMXXVI</p>
            <h1 id="hero-title">Caliber&nbsp;08</h1>
            <p className="hero__lead">
              A manual-winding mechanical movement, made in a run of 200 and then never again.
            </p>
            <dl className="keyfigs">
              {[['72 h', 'power reserve'], ['2.5 Hz', 'frequency'], ['214', 'components'], ['200', 'ever made']].map(([v, k]) => (
                <div key={k}><dt>{v}</dt><dd>{k}</dd></div>
              ))}
            </dl>
            <div className="hero__actions">
              <a className="btn" href="#reserve">Reserve a movement</a>
              <a className="btn btn--quiet" href="#power-path">
                Read the movement <ArrowDown size={15} strokeWidth={1.6} aria-hidden="true" />
              </a>
            </div>
          </div>
          <figure className="hero__plate">
            <MovementPlate />
            <figcaption>
              Plate view, 27 jewels shown in ruby. The balance beats as you read.
            </figcaption>
          </figure>
        </section>

        {/* ---------------------------------------------------- Fig. 02 */}
        <Section id="power-path" fig="02" label="Power path" tone="ink">
          <header className="head">
            <h2>Seventy-two hours, released five times a second</h2>
            <p className="deck">
              Seventy-two hours of stored energy, released one escape-wheel tooth at a time, five times a
              second, for three days from a single wind. Six stages, in the order the energy travels.
            </p>
          </header>
          <PowerPath />
        </Section>

        {/* ---------------------------------------------------- Fig. 03 */}
        <Section id="layers" fig="03" label="Construction">
          <header className="head">
            <h2>Four layers, 3.8mm</h2>
            <p className="deck">
              The movement is built up in four layers, front to back. Drawn here to their real thicknesses.
            </p>
          </header>
          <LayerStack />
        </Section>

        {/* ---------------------------------------------------- Fig. 04 */}
        <Section id="specification" fig="04" label="Specification">
          <header className="head head--tight">
            <h2>Specification</h2>
          </header>
          <dl className="specs">
            {SPECS.map(([k, v]) => (
              <div className="specs__row" key={k}>
                <dt>{k}</dt>
                <dd>{v}</dd>
              </div>
            ))}
          </dl>
        </Section>

        {/* ---------------------------------------------------- Fig. 05 */}
        <Section id="workshop" fig="05" label="The workshop">
          <div className="atelier">
            <figure className="atelier__plate">
              <img
                src={atelier1100}
                srcSet={`${atelier640} 640w, ${atelier1100} 1100w`}
                sizes="(max-width: 900px) 92vw, 46vw"
                width="1100" height="733" loading="lazy" decoding="async"
                alt="Engraved view of an eighteenth-century watchmaking workshop: four craftsmen at benches under tall windows, clocks and cases along the walls."
              />
              <figcaption>
                <em>Horlogerie, Ouvrages et Outils</em>, Plate&nbsp;I — Fossier del., Bénard direxit, from
                Diderot’s <em>Encyclopédie</em>, c.&nbsp;1765. The trade as it was organised two hundred
                years before this movement.{' '}
                <a href="https://commons.wikimedia.org/wiki/File:Horlogerie,_ouvrages_et_outils,_G.36567.jpg"
                  target="_blank" rel="noreferrer">
                  Musée Carnavalet, CC0 <ArrowUpRight size={12} strokeWidth={1.8} aria-hidden="true" />
                </a>
              </figcaption>
            </figure>
            <div className="atelier__facts">
              <h2>Eleven watchmakers, and then the tooling is retired</h2>
              <p className="pullnum"><span>200</span> movements, in total, for ever</p>
              <ul>
                {ATELIER.map((a, i) => (
                  <li key={a}><span className="atelier__no">{pad(i + 1)}</span>{a}</li>
                ))}
              </ul>
            </div>
          </div>
        </Section>

        {/* ---------------------------------------------------- Fig. 06 */}
        <Section id="finishes" fig="06" label="Finishes">
          <header className="head">
            <h2>Three finishes</h2>
            <p className="deck">
              The same 214 components, finished three ways. Prices are for the movement alone; casing is
              arranged separately.
            </p>
          </header>
          <ul className="configs">
            {CONFIGURATIONS.map((c) => {
              const selected = config === c.id
              return (
                <li key={c.id} className={`config${selected ? ' is-selected' : ''}`}>
                  <div className="config__head">
                    <h3>{c.name}</h3>
                    <span className="config__tag">{selected ? 'Selected' : `${c.remaining} left`}</span>
                  </div>
                  <p className="config__price">
                    <span className="config__cur">CHF</span> {chf(c.price)}
                  </p>
                  <p className="config__finish">{c.finish}</p>
                  <dl className="config__meta">
                    <div><dt>Delivery</dt><dd>{c.lead}</dd></div>
                    <div><dt>Allocation</dt><dd>{c.remaining} of the run still unallocated</dd></div>
                  </dl>
                  <button type="button" className="btn btn--block" onClick={() => pick(c.id)}
                    aria-pressed={selected}>
                    {selected ? (<><Check size={15} strokeWidth={2} aria-hidden="true" /> Chosen</>) : 'Choose this finish'}
                  </button>
                </li>
              )
            })}
          </ul>
        </Section>

        {/* ---------------------------------------------------- Fig. 07 */}
        <Section id="reserve" fig="07" label="Reservation">
          <div className="reserve" ref={formRef}>
            <div className="reserve__side">
              <h2>Reserve a movement</h2>
              <p className="reserve__terms">
                Reservations are not binding and no payment is taken now. We will write once, with the
                timing record of the movement allocated to you.
              </p>
              <div className={`ticket${chosen ? ' is-filled' : ''}`} aria-hidden="true">
                {chosen ? (
                  <>
                    <p className="ticket__name">{chosen.name}</p>
                    <p className="ticket__price">CHF {chf(chosen.price)}</p>
                    <p className="ticket__lead">{chosen.lead}</p>
                    <p className="ticket__rem">{chosen.remaining} of the run still unallocated</p>
                  </>
                ) : (
                  <p className="ticket__empty">No finish chosen yet</p>
                )}
              </div>
            </div>

            {reserved ? (
              <div className="confirm" role="status">
                <p className="confirm__mark"><Check size={18} strokeWidth={2} aria-hidden="true" /> Reserved</p>
                <p className="confirm__body">
                  Reserved. {name}, we have held one {chosen.name} movement at CHF{' '}
                  {chf(chosen.price)} and will write to {email}. {chosen.lead}.
                </p>
                <p className="confirm__note">
                  Reservations are not binding and no payment is taken now.
                </p>
              </div>
            ) : (
              <form onSubmit={handleSubmit} className="form">
                <div className="field">
                  <label htmlFor="config">Which finish?</label>
                  <div className="select">
                    <select id="config" name="config" required value={config}
                      onChange={(e) => setConfig(e.target.value)}>
                      <option value="">Choose a finish</option>
                      {CONFIGURATIONS.map((c) => (
                        <option key={c.id} value={c.id}>
                          {c.name} — CHF {chf(c.price)}
                        </option>
                      ))}
                    </select>
                    <ChevronDown size={16} strokeWidth={1.8} aria-hidden="true" />
                  </div>
                </div>
                <div className="field">
                  <label htmlFor="name">Your name</label>
                  <input id="name" name="name" type="text" required value={name}
                    onChange={(e) => setName(e.target.value)} autoComplete="name" />
                </div>
                <div className="field">
                  <label htmlFor="email">Email</label>
                  <input id="email" name="email" type="email" required value={email}
                    onChange={(e) => setEmail(e.target.value)} autoComplete="email" />
                </div>
                <button type="submit" className="btn btn--solid btn--block">Reserve a movement</button>
              </form>
            )}
          </div>
        </Section>
      </main>

      <footer className="foot">
        <p className="foot__mark">Aubry &amp; Vent. Caliber 08. © 2026.</p>
        <p className="foot__mail">
          <Mail size={14} strokeWidth={1.6} aria-hidden="true" />
          Enquiries: <a href="mailto:atelier@aubryvent.ch">atelier@aubryvent.ch</a>
        </p>
        <p className="foot__links">
          <a href="#workshop">Servicing</a>
          <a href="#workshop">Provenance</a>
          <a href="#reserve">Terms of reservation</a>
        </p>
      </footer>
    </div>
  )
}

/* =====================================================================
   Caliber 08 — Aubry & Vent
   The page is the movement's technical plate: numbered figures, an
   annotation rail, rule work at engraving weight, and one accent taken
   from the blued steel of the screws.
   ===================================================================== */

:root {
  /* paper and ink */
  --paper:      #EDE7DA;
  --paper-hi:   #F6F2E8;
  --paper-lo:   #E2DACA;
  --ink:        #17140E;
  --ink-2:      #3B362B;
  --muted:      #6E6857;
  --rule:       #CDC4AF;
  --rule-soft:  #DCD4C2;

  /* materials */
  --blued:      #2C4F7C;   /* thermally blued screw */
  --blued-lo:   #5A82B4;
  --ruby:       #8E2C2A;   /* the 27 jewels */
  --silver:     #B7B1A1;   /* German silver */

  /* dark band */
  --dark:       #14120C;
  --dark-2:     #1F1C14;
  --on-dark:    #E7E1D2;
  --on-dark-2:  #A49C87;

  --ease-out: cubic-bezier(.2, .8, .3, 1);
  --ease-in-out: cubic-bezier(.6, 0, .3, 1);
  --t-fast: 120ms;
  --t-base: 180ms;
  --t-slow: 320ms;

  /* one balance period: 2.5 Hz = 5 semi-oscillations a second */
  --beat: 400ms;

  --sans: 'IBM Plex Sans', ui-sans-serif, system-ui, sans-serif;
  --serif: 'Instrument Serif', 'Iowan Old Style', Georgia, serif;
  --mono: 'IBM Plex Mono', ui-monospace, 'SFMono-Regular', monospace;

  --gutter: clamp(20px, 4.5vw, 60px);
  --rail: 132px;
  --maxw: 1240px;
}

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; scroll-padding-top: 86px; }

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.6;
  font-feature-settings: 'kern' 1;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

h1, h2, h3 { margin: 0; font-weight: 400; }
p { margin: 0; }
ul, ol, dl, dd { margin: 0; padding: 0; }
li { list-style: none; }
img, svg { display: block; max-width: 100%; }

a { color: inherit; }

/* ---------- ambient layer: one grammar, everywhere ---------- */

a, button, select, input, .config, .stage, .layer, .plateg {
  transition:
    color var(--t-fast) var(--ease-out),
    background-color var(--t-fast) var(--ease-out),
    border-color var(--t-fast) var(--ease-out),
    opacity var(--t-fast) var(--ease-out),
    box-shadow var(--t-base) var(--ease-out),
    transform var(--t-base) var(--ease-out);
}

:where(a, button, select, input, [tabindex]):focus-visible {
  outline: 2px solid var(--blued);
  outline-offset: 3px;
  border-radius: 1px;
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    transition-duration: 1ms !important;
    animation-duration: 1ms !important;
    animation-iteration-count: 1 !important;
  }
}

/* =====================================================================
   Top bar
   ===================================================================== */

.topbar {
  position: sticky;
  top: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 10px var(--gutter);
  background: color-mix(in oklab, var(--paper) 88%, transparent);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--rule);
}

.topbar__mark { display: flex; align-items: baseline; gap: 12px; text-decoration: none; }
.topbar__house { font-family: var(--serif); font-size: 20px; letter-spacing: .01em; }
.topbar__cal {
  font-family: var(--mono); font-size: 10.5px; letter-spacing: .14em;
  text-transform: uppercase; color: var(--muted);
  padding-left: 12px; border-left: 1px solid var(--rule);
}

.topbar__nav { display: flex; gap: 20px; margin-left: auto; }
.topbar__nav a {
  font-family: var(--mono); font-size: 11px; letter-spacing: .1em;
  text-transform: uppercase; color: var(--muted);
  text-decoration: none; padding-bottom: 2px;
  border-bottom: 1px solid transparent;
}
.topbar__nav a:hover { color: var(--ink); border-bottom-color: var(--blued); }

.beat { display: flex; align-items: center; gap: 8px; }
.beat__hz { font-family: var(--mono); font-size: 11px; letter-spacing: .08em; color: var(--muted); }
.beat__mark {
  position: relative; width: 18px; height: 18px;
  border: 1px solid var(--rule); border-radius: 50%;
  display: grid; place-items: center;
}
.beat__mark > span {
  width: 12px; height: 1px; background: var(--blued);
  transform-origin: 50% 50%;
  animation: swing var(--beat) var(--ease-in-out) infinite alternate;
}
@keyframes swing { from { transform: rotate(-42deg); } to { transform: rotate(42deg); } }

/* =====================================================================
   Section frame — figure rail is the continuity device
   ===================================================================== */

.section {
  display: grid;
  grid-template-columns: var(--rail) minmax(0, 1fr);
  gap: 0 32px;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: clamp(64px, 8vw, 116px) var(--gutter);
  border-top: 1px solid var(--rule);
}

.section__rail { position: sticky; top: 86px; align-self: start; padding-top: 6px; }
.fig {
  display: block; font-family: var(--mono); font-size: 12px;
  letter-spacing: .06em; color: var(--ink);
}
.fig-label {
  display: block; margin-top: 4px; font-family: var(--mono);
  font-size: 10.5px; letter-spacing: .14em; text-transform: uppercase; color: var(--muted);
}

/* one full-bleed inversion on the route: the movement running in the dark */
.section--ink {
  max-width: none;
  background: var(--dark);
  color: var(--on-dark);
  border-top: none;
  padding-inline: max(var(--gutter), calc(50vw - var(--maxw) / 2 + var(--gutter)));
}
.section--ink .fig { color: var(--on-dark); }
.section--ink .fig-label,
.section--ink .deck { color: var(--on-dark-2); }

.head { max-width: 40ch; margin-bottom: clamp(36px, 5vw, 60px); }
.head--tight { margin-bottom: 28px; }
.head h2 {
  font-family: var(--serif);
  font-size: clamp(30px, 4.2vw, 46px);
  line-height: 1.08;
  letter-spacing: -.015em;
  text-wrap: balance;
}
.deck { margin-top: 16px; max-width: 62ch; color: var(--ink-2); font-size: 16.5px; }

/* regional entrance — against the top of the viewport, once, never on load */
.section__body > *, .section .head { opacity: 0; transform: translateY(14px); }
.section.is-in .section__body > *,
.section.is-in .head { opacity: 1; transform: none; transition: opacity var(--t-slow) var(--ease-out), transform var(--t-slow) var(--ease-out); }
.section.is-in .section__body > *:nth-child(2) { transition-delay: 70ms; }

/* =====================================================================
   Fig. 01 — hero
   ===================================================================== */

.hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, .82fr);
  gap: clamp(32px, 5vw, 72px);
  align-items: center;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: clamp(48px, 7vw, 92px) var(--gutter) clamp(56px, 7vw, 96px);
}

.eyebrow {
  font-family: var(--mono); font-size: 11px; letter-spacing: .16em;
  text-transform: uppercase; color: var(--muted);
}

.hero h1 {
  font-family: var(--serif);
  font-size: clamp(64px, 12.5vw, 168px);
  line-height: .86;
  letter-spacing: -.03em;
  margin: 18px 0 0;
}

.hero__lead {
  margin-top: 22px;
  max-width: 34ch;
  font-size: clamp(17px, 1.6vw, 21px);
  line-height: 1.45;
  color: var(--ink-2);
}

.keyfigs {
  display: flex; flex-wrap: wrap;
  margin-top: 34px;
  border-top: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
}
.keyfigs > div {
  flex: 1 1 84px; padding: 14px 16px 13px;
  border-right: 1px solid var(--rule-soft);
}
.keyfigs > div:first-child { padding-left: 0; }
.keyfigs > div:last-child { border-right: none; }
.keyfigs dt {
  font-family: var(--mono); font-size: clamp(17px, 2vw, 22px);
  font-variant-numeric: tabular-nums; letter-spacing: -.01em;
}
.keyfigs dd {
  margin-top: 2px; font-family: var(--mono); font-size: 10px;
  letter-spacing: .12em; text-transform: uppercase; color: var(--muted);
}

.hero__actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 30px; }

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 12px 20px;
  font-family: var(--mono); font-size: 12px; letter-spacing: .1em; text-transform: uppercase;
  text-decoration: none; cursor: pointer;
  background: transparent; color: var(--ink);
  border: 1px solid var(--ink); border-radius: 2px;
}
.btn:hover { background: var(--ink); color: var(--paper-hi); transform: translateY(-2px); }
.btn:active { transform: translateY(0); }
.btn--quiet { border-color: var(--rule); color: var(--muted); }
.btn--quiet:hover { background: transparent; color: var(--ink); border-color: var(--ink); }
.btn--solid { background: var(--ink); color: var(--paper-hi); }
.btn--solid:hover { background: var(--blued); border-color: var(--blued); }
.btn--block { width: 100%; }

.hero__plate { margin: 0; }
.hero__plate figcaption {
  margin-top: 14px; font-family: var(--mono); font-size: 10.5px;
  letter-spacing: .04em; color: var(--muted); text-align: right;
}

/* --- the plate drawing ------------------------------------------------ */

.plate-svg { width: 100%; height: auto; overflow: visible; }
.plate-svg circle, .plate-svg path { fill: none; }

.ln-plate  { stroke: var(--ink); stroke-width: 1.4; }
.ln-hair   { stroke: var(--rule); stroke-width: .7; }
.ln-part   { stroke: var(--ink-2); stroke-width: .9; }
.ln-escape { stroke: var(--ink); stroke-width: 1; }
.ln-bridge { stroke: var(--ink); stroke-width: 1.1; fill: color-mix(in oklab, var(--silver) 26%, transparent); }
.ln-spring { stroke: var(--blued); stroke-width: .8; }
.ln-weight { stroke: var(--ink); stroke-width: .9; fill: var(--paper-lo); }
.ln-pivot  { fill: var(--ruby); stroke: none; }
.ln-frost  { stroke: var(--rule-soft); stroke-width: .45; opacity: .8; }
.jewel     { fill: var(--ruby); opacity: .85; stroke: none; }

.balance-spin {
  transform-origin: 112px 306px;
  animation: beat var(--beat) var(--ease-in-out) infinite alternate;
}
@keyframes beat { from { transform: rotate(-38deg); } to { transform: rotate(38deg); } }

.dim path { stroke: var(--muted); stroke-width: .6; }
.dim text, .leader text {
  font-family: var(--mono); font-size: 10px; letter-spacing: .06em;
  fill: var(--muted); stroke: none;
}
.dim text { fill: var(--ink-2); }
.leader path { stroke: var(--rule); stroke-width: .6; }

/* =====================================================================
   Fig. 02 — power path (the peak)
   ===================================================================== */

.path__list { border-top: 1px solid color-mix(in oklab, var(--on-dark) 18%, transparent); }

.stage {
  display: grid;
  grid-template-columns: 88px minmax(0, 1fr) minmax(0, 20ch);
  gap: 0 28px;
  align-items: center;
  padding: 22px 12px 22px 0;
  border-bottom: 1px solid color-mix(in oklab, var(--on-dark) 14%, transparent);
  cursor: default;
}
.stage:hover, .stage.is-active { background: color-mix(in oklab, var(--on-dark) 5%, transparent); }

.stage__spine { position: relative; height: 100%; display: grid; place-items: center; }
.stage__spine::before {
  content: ''; position: absolute; left: 43px; top: -24px; bottom: -24px;
  width: 1px; background: color-mix(in oklab, var(--on-dark) 22%, transparent);
}
.stage:first-child .stage__spine::before { top: 50%; }
.stage:last-child .stage__spine::before { bottom: 50%; }

.stage__node {
  position: relative; z-index: 1;
  width: 62px; height: 62px; border-radius: 50%;
  display: grid; place-items: center;
  background: var(--dark);
  border: 1px solid color-mix(in oklab, var(--on-dark) 26%, transparent);
}
.glyph { width: 34px; height: 34px; fill: none; stroke: var(--on-dark-2); stroke-width: 1.1; }
.stage.is-active .glyph { stroke: var(--paper-hi); }
.stage.is-active .stage__node { border-color: var(--blued-lo); }

/* the wind, tracked down the spine: one period, six stations */
.path.is-live .stage__node::after {
  content: ''; position: absolute; inset: -5px; border-radius: 50%;
  border: 1px solid var(--blued-lo); opacity: 0;
  animation: fire 4800ms linear infinite;
  animation-delay: calc(var(--i) * 800ms);
}
@keyframes fire {
  0%   { opacity: 0; transform: scale(.72); }
  4%   { opacity: .95; transform: scale(1); }
  14%  { opacity: 0; transform: scale(1.22); }
  100% { opacity: 0; transform: scale(1.22); }
}

.stage__name { font-size: 17px; display: flex; align-items: baseline; gap: 12px; }
.stage__no {
  font-family: var(--mono); font-size: 11px; letter-spacing: .08em;
  color: var(--on-dark-2);
}
.stage__detail {
  margin-top: 5px; font-size: 14.5px; line-height: 1.5;
  color: var(--on-dark-2); max-width: 52ch;
}
.stage__figure {
  font-family: var(--mono);
  font-size: clamp(13px, 1.35vw, 16px);
  line-height: 1.35;
  font-variant-numeric: tabular-nums;
  color: var(--paper-hi);
  text-align: right;
  padding-left: 20px;
  border-left: 1px solid color-mix(in oklab, var(--on-dark) 16%, transparent);
}
.stage.is-active .stage__figure { color: var(--blued-lo); }

.path__foot {
  display: flex; align-items: center; gap: 10px; margin-top: 20px;
  font-family: var(--mono); font-size: 10.5px; letter-spacing: .12em;
  text-transform: uppercase; color: var(--on-dark-2);
}
.pulse-key {
  width: 9px; height: 9px; border-radius: 50%; border: 1px solid var(--blued-lo);
  animation: fire 4800ms linear infinite;
}

/* =====================================================================
   Fig. 03 — the four layers
   ===================================================================== */

.stack {
  display: grid;
  grid-template-columns: minmax(0, .78fr) minmax(0, 1fr);
  gap: clamp(24px, 4vw, 56px);
  align-items: start;
}

.stack__svg { width: 100%; height: auto; overflow: visible; }
.stack__axis path { stroke: var(--rule); stroke-width: 1; fill: none; }
.stack__axis text {
  font-family: var(--mono); font-size: 10px; letter-spacing: .12em;
  text-transform: uppercase; fill: var(--muted);
}

.plateg { cursor: default; transform: translateY(0); }
.plateg__top { fill: var(--paper-hi); stroke: var(--ink); stroke-width: 1; }
.plateg__side { fill: var(--paper-lo); stroke: var(--ink); stroke-width: 1; }
.plateg__side2 { fill: var(--silver); stroke: var(--ink); stroke-width: 1; }
.plateg__lead { stroke: var(--rule); stroke-width: .7; fill: none; }
.plateg__mm {
  font-family: var(--mono); font-size: 11px; font-variant-numeric: tabular-nums;
  fill: var(--muted);
}
.plateg.is-active .plateg__top { fill: color-mix(in oklab, var(--blued) 12%, var(--paper-hi)); }
.plateg.is-active .plateg__side2 { fill: color-mix(in oklab, var(--blued) 34%, var(--silver)); }
.plateg.is-active .plateg__mm { fill: var(--ink); }

/* the plates arrive stacked closed, then separate — that is the point */
.stack .plateg { transform: translateY(calc(var(--i) * -30px)); }
.stack.is-in .plateg {
  transform: translateY(0);
  transition: transform 620ms var(--ease-out);
  transition-delay: calc(var(--i) * 70ms);
}

.stack__list { border-top: 1px solid var(--rule); }
.layer {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr) 62px;
  gap: 4px 14px;
  padding: 16px 8px 16px 0;
  border-bottom: 1px solid var(--rule-soft);
  cursor: default;
}
.layer:hover, .layer.is-active { background: var(--paper-hi); box-shadow: inset 2px 0 0 var(--blued); }
.layer__no { font-family: var(--mono); font-size: 11px; color: var(--muted); padding-top: 3px; }
.layer__name { font-size: 16.5px; }
.layer__mm {
  font-family: var(--mono); font-size: 14px; font-variant-numeric: tabular-nums;
  text-align: right;
}
.layer__note { grid-column: 2 / -1; font-size: 14px; color: var(--muted); line-height: 1.5; }
.layer.is-active .layer__note { color: var(--ink-2); }

.stack__total {
  grid-column: 1 / -1;
  margin-top: 8px; padding-top: 16px;
  border-top: 1px solid var(--rule);
  font-family: var(--mono); font-size: 12px; letter-spacing: .06em;
  color: var(--muted);
}
.stack__total span { color: var(--ink); font-size: 15px; }

/* =====================================================================
   Fig. 04 — specification
   ===================================================================== */

.specs {
  columns: 2;
  column-gap: clamp(28px, 5vw, 72px);
  border-top: 1px solid var(--ink);
}
.specs__row {
  break-inside: avoid;
  display: flex; align-items: baseline; gap: 12px;
  padding: 13px 0;
  border-bottom: 1px solid var(--rule-soft);
}
.specs__row dt {
  font-family: var(--mono); font-size: 10.5px; letter-spacing: .12em;
  text-transform: uppercase; color: var(--muted); white-space: nowrap;
}
.specs__row::after {
  content: ''; flex: 1 1 auto; height: 1px;
  background: repeating-linear-gradient(90deg, var(--rule) 0 1px, transparent 1px 5px);
  transform: translateY(-3px);
}
.specs__row dd {
  font-family: var(--mono); font-size: 15px; font-variant-numeric: tabular-nums;
  text-align: right; white-space: nowrap;
}

/* =====================================================================
   Fig. 05 — the workshop
   ===================================================================== */

.atelier {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
  gap: clamp(28px, 4.5vw, 64px);
  align-items: start;
}

.atelier__plate { margin: 0; }
.atelier__plate img {
  width: 100%; height: auto;
  border: 1px solid var(--rule);
  background: var(--paper-hi);
  filter: sepia(.12) contrast(1.04);
}
.atelier__plate figcaption {
  margin-top: 12px; font-size: 12.5px; line-height: 1.55; color: var(--muted);
  max-width: 46ch;
}
.atelier__plate figcaption a {
  font-family: var(--mono); font-size: 11px; white-space: nowrap;
  text-decoration: none; border-bottom: 1px solid var(--rule);
  display: inline-flex; align-items: center; gap: 3px;
}
.atelier__plate figcaption a:hover { color: var(--blued); border-bottom-color: var(--blued); }

.atelier__facts h2 {
  font-family: var(--serif);
  font-size: clamp(28px, 3.6vw, 42px); line-height: 1.08; letter-spacing: -.015em;
  max-width: 18ch;
}
.pullnum {
  display: flex; align-items: baseline; gap: 14px;
  margin: 26px 0 8px; padding-bottom: 18px;
  border-bottom: 1px solid var(--rule);
  font-family: var(--mono); font-size: 12.5px; letter-spacing: .06em; color: var(--muted);
}
.pullnum span {
  font-family: var(--serif); font-size: clamp(56px, 8vw, 92px);
  line-height: .8; letter-spacing: -.02em; color: var(--ink);
}
.atelier__facts ul { display: grid; }
.atelier__facts li {
  display: grid; grid-template-columns: 34px minmax(0, 1fr);
  padding: 14px 0; border-bottom: 1px solid var(--rule-soft);
  font-size: 15px; line-height: 1.55; color: var(--ink-2);
}
.atelier__no { font-family: var(--mono); font-size: 11px; color: var(--muted); padding-top: 4px; }

/* =====================================================================
   Fig. 06 — three finishes
   ===================================================================== */

.configs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1px;
  background: var(--rule);
  border: 1px solid var(--rule);
}
.config {
  display: flex; flex-direction: column;
  background: var(--paper);
  padding: 24px 22px 22px;
}
.config:hover { background: var(--paper-hi); }
.config.is-selected { background: var(--dark); color: var(--on-dark); }

.config__head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }
.config h3 { font-family: var(--serif); font-size: 25px; line-height: 1.1; letter-spacing: -.01em; }
.config__tag {
  font-family: var(--mono); font-size: 10px; letter-spacing: .12em; text-transform: uppercase;
  color: var(--muted); white-space: nowrap; padding-top: 4px;
}
.config.is-selected .config__tag { color: var(--blued-lo); }

.config__price {
  margin-top: 18px;
  font-family: var(--mono); font-size: clamp(24px, 2.6vw, 31px);
  font-variant-numeric: tabular-nums; letter-spacing: -.02em;
}
.config__cur { font-size: 13px; letter-spacing: .1em; color: var(--muted); }
.config.is-selected .config__cur { color: var(--on-dark-2); }

.config__finish {
  margin-top: 14px; font-size: 14.5px; line-height: 1.55; color: var(--ink-2);
  padding-bottom: 18px;
}
.config.is-selected .config__finish { color: var(--on-dark-2); }

.config__meta { margin-top: auto; border-top: 1px solid var(--rule-soft); }
.config.is-selected .config__meta { border-top-color: color-mix(in oklab, var(--on-dark) 20%, transparent); }
.config__meta > div { padding: 11px 0; }
.config__meta dt {
  font-family: var(--mono); font-size: 9.5px; letter-spacing: .14em;
  text-transform: uppercase; color: var(--muted);
}
.config.is-selected .config__meta dt { color: var(--on-dark-2); }
.config__meta dd { font-size: 14px; margin-top: 2px; }
.config .btn { margin-top: 16px; }
.config.is-selected .btn { border-color: var(--on-dark); color: var(--on-dark); }
.config.is-selected .btn:hover { background: var(--on-dark); color: var(--dark); }

/* =====================================================================
   Fig. 07 — reservation
   ===================================================================== */

.reserve {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, .82fr);
  gap: clamp(28px, 5vw, 72px);
  align-items: start;
}
.reserve h2 {
  font-family: var(--serif); font-size: clamp(30px, 4vw, 44px);
  line-height: 1.06; letter-spacing: -.015em;
}
.reserve__terms { margin-top: 16px; max-width: 44ch; color: var(--ink-2); }

.ticket {
  margin-top: 28px; padding: 20px;
  border: 1px solid var(--rule);
  border-left: 3px solid var(--rule);
  background: var(--paper-hi);
}
.ticket.is-filled { border-left-color: var(--blued); }
.ticket__empty, .ticket__rem {
  font-family: var(--mono); font-size: 11px; letter-spacing: .1em;
  text-transform: uppercase; color: var(--muted);
}
.ticket__name { font-family: var(--serif); font-size: 24px; line-height: 1.15; }
.ticket__price {
  font-family: var(--mono); font-size: 20px; font-variant-numeric: tabular-nums;
  margin-top: 6px;
}
.ticket__lead { font-size: 14px; color: var(--ink-2); margin-top: 4px; }
.ticket__rem { margin-top: 10px; }

.form {
  display: grid; gap: 18px;
  padding: 26px;
  border: 1px solid var(--ink);
  background: var(--paper-hi);
}
.field { display: grid; gap: 7px; }
.field label {
  font-family: var(--mono); font-size: 10.5px; letter-spacing: .14em;
  text-transform: uppercase; color: var(--muted);
}
.field input, .field select {
  width: 100%;
  font-family: var(--sans); font-size: 15.5px; color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--rule);
  border-radius: 2px;
  padding: 11px 12px;
  min-height: 46px;
}
.field select { appearance: none; padding-right: 38px; }
.field input:hover, .field select:hover { border-color: var(--ink-2); }
.field input:focus, .field select:focus {
  outline: none; border-color: var(--blued);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--blued) 16%, transparent);
}
.select { position: relative; display: grid; }
.select svg { position: absolute; right: 13px; top: 50%; transform: translateY(-50%); pointer-events: none; color: var(--muted); }

.confirm { padding: 26px; border: 1px solid var(--blued); background: var(--paper-hi); }
.confirm__mark {
  display: flex; align-items: center; gap: 8px;
  font-family: var(--mono); font-size: 12px; letter-spacing: .14em;
  text-transform: uppercase; color: var(--blued);
}
.confirm__body {
  margin-top: 14px; font-family: var(--serif); font-size: 21px; line-height: 1.35;
}
.confirm__note { margin-top: 14px; font-size: 13.5px; color: var(--muted); }

/* =====================================================================
   Footer
   ===================================================================== */

.foot {
  display: flex; flex-wrap: wrap; align-items: center; gap: 16px 32px;
  max-width: var(--maxw); margin: 0 auto;
  padding: 26px var(--gutter) 44px;
  border-top: 1px solid var(--ink);
  font-family: var(--mono); font-size: 11.5px; letter-spacing: .04em; color: var(--muted);
}
.foot__mail { display: flex; align-items: center; gap: 7px; }
.foot__links { display: flex; gap: 20px; margin-left: auto; }
.foot a { text-decoration: none; border-bottom: 1px solid var(--rule); padding-bottom: 1px; }
.foot a:hover { color: var(--ink); border-bottom-color: var(--blued); }

/* =====================================================================
   Narrow — 390px is its own composition
   ===================================================================== */

@media (max-width: 1000px) {
  .hero { grid-template-columns: 1fr; }
  .hero__plate { order: -1; max-width: 440px; }
  .hero__plate figcaption { text-align: left; }
  .stack, .atelier, .reserve { grid-template-columns: 1fr; }
  .configs { grid-template-columns: 1fr; }
  .config { padding: 20px; }
  .specs { columns: 1; }
}

@media (max-width: 760px) {
  :root { --rail: 0px; }

  .topbar { padding: 8px var(--gutter); gap: 12px; }
  .topbar__nav { display: none; }
  .topbar__cal { padding-left: 10px; }
  .beat { margin-left: auto; }

  .section {
    grid-template-columns: 1fr;
    gap: 14px;
    padding-block: clamp(48px, 11vw, 72px);
  }
  .section__rail {
    position: static;
    display: flex; align-items: baseline; gap: 12px;
    padding-bottom: 10px; border-bottom: 1px solid var(--rule);
    margin-bottom: 12px;
  }
  .fig-label { margin-top: 0; }

  .hero { padding-top: 28px; }
  .hero h1 { font-size: clamp(58px, 19vw, 96px); }
  .keyfigs > div { flex-basis: 45%; border-bottom: 1px solid var(--rule-soft); }
  .keyfigs > div:nth-child(2n) { border-right: none; }
  .keyfigs > div:nth-child(3) { padding-left: 0; }
  .hero__actions .btn { flex: 1 1 auto; }

  /* the power path becomes a vertical ledger: figure under the name */
  .stage {
    grid-template-columns: 58px minmax(0, 1fr);
    gap: 0 16px;
    padding: 18px 0;
  }
  .stage__spine::before { left: 28px; }
  .stage__node { width: 44px; height: 44px; }
  .glyph { width: 24px; height: 24px; }
  .stage__name { font-size: 16px; }
  .stage__figure {
    grid-column: 2; text-align: left; padding: 10px 0 0;
    border-left: none; margin-top: 8px;
    border-top: 1px solid color-mix(in oklab, var(--on-dark) 16%, transparent);
    font-size: 13px;
  }

  .stack__svg { max-width: 420px; margin-inline: auto; }
  .layer { grid-template-columns: 26px minmax(0, 1fr) 54px; }

  .pullnum { margin-top: 20px; }
  .atelier__plate figcaption { font-size: 12px; }

  .form { padding: 20px; }
  .foot { gap: 12px 20px; padding-bottom: 36px; }
  .foot__links { margin-left: 0; flex-wrap: wrap; }
}

@media (max-width: 380px) {
  .keyfigs > div { flex-basis: 100%; border-right: none; padding-left: 0; }
  .stage { grid-template-columns: 46px minmax(0, 1fr); }
  .stage__spine::before { left: 22px; }
  .stage__node { width: 38px; height: 38px; }
}

